/** Build a UPI deeplink (works with GPay / PhonePe / Paytm). */

function buildUpiUrl({
  upi_id,
  payee_name,
  amount,
  note,
  txn_ref
}) {
  const params = new URLSearchParams({
    pa: upi_id,
    pn: payee_name,
    am: String(amount),
    cu: "INR"
  });
  if (note) params.set("tn", note);
  if (txn_ref) params.set("tr", txn_ref);
  return `upi://pay?${params.toString()}`;
}

